import {immuneUnits,immuneMissions,initialImmuneState,chooseImmuneUnit,advanceImmuneState} from './studio-data.js';
import {immuneArt} from './studio-art.js';
export function createImmuneJourney(root,api){
 let state=initialImmuneState(),pair=false,lastChoice='',log=[];
 root.innerHTML=`<div class="studio-section-head"><div><span class="studio-kicker">03 / BIODEFENSE</span><h2>Bảo vệ sự sống, bằng hiểu biết.</h2><p>Mỗi tế bào có một vai trò. Đọc tình huống, chọn người thực hiện và quan sát cơ chế thay vì chỉ “bắn” mọi thứ ra khỏi cơ thể.</p></div><span class="studio-label">LỚP 11 · MIỄN DỊCH</span></div><div class="immune-toolbar"><div class="studio-button-row" role="group" aria-label="Chọn nhiệm vụ miễn dịch"><button type="button" data-immune-mission="bacteria">Vết xước trong khu vườn</button><button type="button" data-immune-mission="virus">Tế bào nhiễm virus</button></div><label for="immune-mode">Cách chơi <select id="immune-mode"><option value="solo">Một người khám phá</option><option value="pair">Hai người chung thiết bị</option></select></label></div><div class="immune-layout"><div class="immune-observation"><div class="immune-scene-heading"><span class="studio-kicker" id="immune-subtitle"></span><span id="immune-turn"></span></div><div id="immune-art"></div><ol class="immune-timeline" id="immune-timeline" aria-label="Các bước đáp ứng minh họa"></ol><div class="immune-observer-note" id="immune-observer"></div><details class="studio-prompt"><summary>Hiểu giới hạn của mô hình</summary><p>Các bước được tách để dễ học; ngoài cơ thể chúng có thể chồng lấp và diễn ra trên các thang thời gian khác nhau. Mô hình không bao quát bổ thể, NK, điều hòa miễn dịch hay mọi loại tác nhân. Thứ tự không phải quy trình chẩn đoán hoặc điều trị.</p></details></div><div class="immune-command"><span class="studio-kicker" id="immune-stage"></span><h3 id="immune-title"></h3><p id="immune-question"></p><div id="immune-choices" class="immune-choices"></div><div id="immune-feedback" class="immune-feedback" role="status"></div><div class="studio-button-row"><button type="button" id="immune-hint" class="studio-text-button">Một gợi ý nhỏ ↗</button><button type="button" id="immune-next" class="studio-button" hidden>Tiếp tục →</button></div><button type="button" id="immune-save" class="studio-button secondary" hidden>Lưu nhật ký nhiệm vụ</button><button type="button" id="immune-replay" class="studio-text-button" hidden>Khám phá lại ↺</button></div></div><div class="studio-insight"><span>TỪ PHÒNG THỦ ĐẾN CÂU HỎI MỚI</span><p>Kháng thể có thể tác động lên tác nhân ở ngoài tế bào, còn T gây độc nhận diện tế bào nhiễm phù hợp. Chọn đúng mục tiêu cũng quan trọng như chọn đúng “người bảo vệ”.</p></div>`;
 function render(){const mission=immuneMissions[state.mission],step=mission.steps[state.step],finished=state.finished;root.querySelector('#immune-subtitle').textContent=mission.subtitle;root.querySelector('#immune-turn').textContent=pair?`Lượt của bạn ${state.step%2+1}`:'ĐIỀU PHỐI VIÊN / BẠN';root.querySelector('#immune-observer').textContent=pair?`Hai người trên cùng thiết bị. Bạn ${state.step%2+1} chọn tế bào; bạn ${state.step%2===0?2:1} nêu bằng chứng trước khi bấm. Đổi vai sau mỗi bước.`:'Thử dự đoán trước khi chọn: tế bào nào phù hợp, và vì sao những lựa chọn còn lại chưa phù hợp?';
 root.querySelector('#immune-stage').textContent=finished?'NHIỆM VỤ ĐÃ HOÀN THÀNH':`TÌNH HUỐNG ${state.step+1} / ${mission.steps.length}`;root.querySelector('#immune-title').textContent=finished?'Bạn đã nối được các vai trò.':step.title;root.querySelector('#immune-question').textContent=finished?`Đã đi qua ${mission.steps.length} bước của “${mission.title}”. Có ${state.errors} lần cần xem lại lựa chọn. Lưu câu chuyện để giải thích bằng lời của bạn.`:step.question;
 root.querySelector('#immune-art').innerHTML=immuneArt({step:state.step,unitId:finished?'memory':state.confirmed?step.correct:'',unit:finished?'Tế bào nhớ':state.confirmed?immuneUnits[step.correct].name:'Tế bào miễn dịch',virus:state.mission==='virus',complete:finished});
 root.querySelector('#immune-timeline').innerHTML=mission.steps.map((s,i)=>`<li class="${i<state.step?'done':i===state.step?'current':''}" ${i===state.step?'aria-current="step"':''}><span>${i<state.step?'✓':i+1}</span>${s.title}</li>`).join('');
 root.querySelector('#immune-choices').innerHTML=finished?'':step.choices.map(id=>{const unit=immuneUnits[id];return `<button type="button" data-immune-unit="${id}" class="${lastChoice===id?'chosen':''} ${state.confirmed&&id===step.correct?'correct':''}" ${state.confirmed?'disabled':''}><span class="immune-unit-symbol unit-${id}" aria-hidden="true"></span><span><small>${unit.tag}</small><strong>${unit.name}</strong></span><span aria-hidden="true">${state.confirmed&&id===step.correct?'✓':'↗'}</span></button>`}).join('');
 const feedback=root.querySelector('#immune-feedback');feedback.classList.toggle('is-correct',state.confirmed);feedback.textContent=finished?'Hoàn thành ở đây thể hiện bạn đã khám phá mô hình, không phải chứng nhận năng lực y khoa.':state.confirmed?step.why:lastChoice?`${immuneUnits[lastChoice].description} Ở tình huống này, hãy tìm vai trò phù hợp hơn.`:mission.intro;
 root.querySelector('#immune-next').hidden=!state.confirmed;root.querySelector('#immune-next').textContent=state.step===mission.steps.length-1?'Kết lại nhiệm vụ →':'Bước tiếp theo →';root.querySelector('#immune-hint').hidden=state.confirmed||finished;root.querySelector('#immune-save').hidden=!finished;root.querySelector('#immune-replay').hidden=!finished;
 root.querySelectorAll('[data-immune-mission]').forEach(b=>{const selected=b.dataset.immuneMission===state.mission;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('selected',selected)});
 }
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.immuneMission){state=initialImmuneState(b.dataset.immuneMission);lastChoice='';log=[];render()}if(b.dataset.immuneUnit){const next=chooseImmuneUnit(state,b.dataset.immuneUnit);if(next===state)return;lastChoice=b.dataset.immuneUnit;state=next;if(state.confirmed)log.push(`${state.step+1}. ${immuneMissions[state.mission].steps[state.step].title}: ${immuneUnits[lastChoice].name}`);render();if(state.confirmed)root.querySelector('#immune-next').focus()}});
 root.querySelector('#immune-next').addEventListener('click',()=>{state=advanceImmuneState(state);lastChoice='';if(state.finished)api.award('immune-'+state.mission,'Đã kết nối một câu chuyện miễn dịch');render();(root.querySelector('[data-immune-unit]')||root.querySelector('#immune-save')).focus()});
 root.querySelector('#immune-hint').addEventListener('click',()=>{root.querySelector('#immune-feedback').textContent=immuneMissions[state.mission].steps[state.step].hint});
 root.querySelector('#immune-save').addEventListener('click',()=>{const m=immuneMissions[state.mission];api.saveNote(`BioDefense: ${m.title}`,`${m.subtitle}\n${pair?'Hai người cùng thiết bị':'Một người khám phá'}\n\n${log.join('\n')}\n\nSố lần xem lại lựa chọn: ${state.errors}.\nMô hình giáo khoa giản lược; các đáp ứng ngoài đời có thể chồng lấp.\n\nCâu hỏi tiếp theo: Điều gì sẽ khác nếu tác nhân ở ngoài tế bào hoặc ở trong tế bào?`)});
 root.querySelector('#immune-replay').addEventListener('click',()=>{state=initialImmuneState(state.mission);lastChoice='';log=[];render()});root.querySelector('#immune-mode').addEventListener('change',e=>{pair=e.target.value==='pair';render()});render();return {setActive(){}};
}
